WITH item_return_stats AS ( SELECT i.i_item_id, i.i_product_name, i.i_category, i.i_current_price, SUM(cr.cr_return_quantity) AS total_return_qty, SUM(cr.cr_return_amount) AS total_return_amount, CASE WHEN SUM(cr.cr_return_quantity) = 0 THEN 0 ELSE SUM(cr.cr_return_amount) / SUM(cr.cr_return_quantity) END AS avg_return_amount_per_qty, AVG(ib.ib_lower_bound) AS avg_income_lower_bound FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN household_demographics hd ON cr.cr_returning_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY i.i_item_id, i.i_product_name, i.i_category, i.i_current_price ) SELECT i_item_id, i_product_name, i_category, i_current_price, total_return_qty, total_return_amount, avg_return_amount_per_qty, avg_income_lower_bound, AVG(avg_return_amount_per_qty) OVER () AS overall_avg_return_per_qty, CASE WHEN avg_return_amount_per_qty > AVG(avg_return_amount_per_qty) OVER () THEN 'Above Avg' ELSE 'Below Avg' END AS return_cost_category, RANK() OVER (ORDER BY avg_return_amount_per_qty DESC) AS return_amount_per_qty_rank FROM item_return_stats ORDER BY return_amount_per_qty_rank LIMIT 20
